"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["39867"],{36502(e){e.exports=JSON.parse('{"id":"F488","slug":"best-execution-price-improvement","name":"Best Execution: Price Improvement and Execution Cost","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"MiFID II","level":"Beginner","aliases":["MiFID II","best execution","price improvement","execution quality","NBBO"],"formula":{"latex":"PI=(P_{ask}-P_{exec})\\\\,q\\\\ \\\\text{(buy)},\\\\quad \\\\text{Cost}=(P_{exec}-P_{mid})\\\\,q","also":[],"text":"For a buy order: price improvement = (best offer at order time - price paid) x shares; Execution cost vs mid-point = (price paid - mid-point) x shares; Effective half-spread paid = (price paid - mid-point) / mid-point; Firms under MiFID II must show they took steps to get the best result for clients, including price, costs, speed and likelihood of execution"},"symbols":[{"symbol":"P_ask, P_bid","meaning":"Best offer and best bid when the order arrived","unit":"money"},{"symbol":"P_mid","meaning":"Mid-point between bid and ask","unit":"money"},{"symbol":"P_exec","meaning":"Price the client actually got","unit":"money"},{"symbol":"q","meaning":"Number of shares","unit":"shares"}],"when_to_use":"Use it to check execution quality, which MiFID II requires firms to monitor and publish. Getting a price better than the best quote means the client gained; paying above the mid-point is the normal cost of trading. It ignores fees, market impact for large orders and the speed of the fill.","worked_example":{"problem":"A client buys 5,000 shares when the quote is 100.00 bid and 100.06 offered. The order executes at 100.04.","inputs":{"b":100,"a":100.06,"e":100.04,"q":5000},"steps":[{"label":"Mid-point","working":"(100.06+100) / 2","value":"100.0300"},{"label":"Price improvement vs best offer","working":"(100.06-100.04) x 5000","value":"100.00"},{"label":"Cost above the mid-point","working":"(100.04-100.03) x 5000","value":"50.00"},{"label":"Effective half-spread","working":"(100.04-100.03) / 100.03","value":"0.010%"},{"label":"Quoted half-spread","working":"(100.06-100.03) / 100.03","value":"0.030%"},{"label":"Share of the half-spread paid","working":"(100.04-100.03) / (100.06-100.03)","value":"33.3%"}],"answer":"The mid-point is 100.0300. The client improved on the best offer by 100.00 and paid 50.00 above the mid-point, an effective half-spread of 0.010%. The quoted half-spread was 0.030%, so the order captured 33.3% of the quoted spread."},"calculator":{"available":true,"inputs":[{"id":"b","label":"Best bid","unit":"money","type":"number","default":100,"hint":""},{"id":"a","label":"Best offer","unit":"money","type":"number","default":100.06,"hint":""},{"id":"e","label":"Execution price (buy)","unit":"money","type":"number","default":100.04,"hint":""},{"id":"q","label":"Shares","unit":"","type":"number","default":5000,"hint":""}],"checks":[{"expr":"a>b and q>0","message":"The offer must be above the bid and shares above zero."}],"steps":[{"id":"mid","label":"Mid-point","expr":"(a+b)/2","format":"num4"},{"id":"pi","label":"Price improvement vs best offer","expr":"(a-e)*q","format":"money"},{"id":"cost","label":"Cost above the mid-point","expr":"(e-mid)*q","format":"money"},{"id":"hs","label":"Effective half-spread","expr":"(e-mid)/mid","format":"pct3"},{"id":"qhs","label":"Quoted half-spread","expr":"(a-mid)/mid","format":"pct3"},{"id":"cap","label":"Share of the half-spread paid","expr":"(e-mid)/(a-mid)","format":"pct1"}],"results":["pi","cost","hs","cap"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"mid":100.03,"pi":99.9999999999801,"cost":50.00000000002558,"hs":9.997000899735196e-5,"qhs":2.9991002699191377e-4,"cap":0.33333333333349124}},"finder":{"finds":"How good an order execution was","needs":"Bid, offer, execution price, shares"},"related":[{"slug":"effective-spread","name":"Effective Spread and Price Impact"},{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost"},{"slug":"implementation-shortfall","name":"Implementation Shortfall and Market Impact"}],"related_ids":["F262","F261","F515"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mi>I</mi><mo>=</mo><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mrow><mi>a</mi><mi>s</mi><mi>k</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>e</mi><mi>x</mi><mi>e</mi><mi>c</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><mi>q</mi><mtext>\xa0(buy)</mtext><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Cost</mtext><mo>=</mo><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mrow><mi>e</mi><mi>x</mi><mi>e</mi><mi>c</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>m</mi><mi>i</mi><mi>d</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><mi>q</mi></mrow><annotation encoding=\\"application/x-tex\\">PI=(P_{ask}-P_{exec})\\\\,q\\\\ \\\\text{(buy)},\\\\quad \\\\text{Cost}=(P_{exec}-P_{mid})\\\\,q</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>P</mi><mi>I</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle PI</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mrow><mi>a</mi><mi>s</mi><mi>k</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>e</mi><mi>x</mi><mi>e</mi><mi>c</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><mi>q</mi><mtext>\xa0(buy)</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =(P_{ask}-P_{exec})\\\\,q\\\\ \\\\text{(buy)}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Cost</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Cost}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mrow><mi>e</mi><mi>x</mi><mi>e</mi><mi>c</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>m</mi><mi>i</mi><mi>d</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><mi>q</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =(P_{exec}-P_{mid})\\\\,q</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"beneish-m-score","name":"Beneish M-Score"},"next":{"slug":"beta","name":"Beta (Regression Slope)"},"lesson":null,"total":522}')}}]);